import { test, expect } from '@playwright/test';
import { ensureCapboSession, fillAngularField, selectMatDropdown, searchList } from './helpers/capbo-ui';

// Serial: View/Edit/Delete operate on the record Create makes.
test.describe.configure({ mode: 'serial' });

test.describe("Vat CRUD", () => {
  test.setTimeout(45_000);
  const suffix = Date.now().toString(36).slice(-5);
  const name = `e2e-vat-${suffix}`;
  const updatedName = `${name}-upd`;

  test('Create Vat with all required fields', async ({ page }) => {
    await ensureCapboSession(page, "/vat");
    await page.getByTestId("vat-create").click({ timeout: 15000 });

    // vat.vatName — mat-input (name)
    await fillAngularField(page, page.getByTestId("vat-name"), name);
    // vat.rate — mat-input (rate)
    await fillAngularField(page, page.getByTestId("vat-rate"), "1");
    // country — countries-dropdown (country)
    await selectMatDropdown(page, page.getByTestId("vat-country"), "__first__");

    const save = page.getByTestId("vat-save");
    await expect(save, 'save must enable once required controls are valid').toBeEnabled({ timeout: 8000 });
    await save.click({ timeout: 15000 });

    await searchList(page, name, {"testId":"vat-search","control":null,"route":"/vat"});
    await expect(page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first()).toBeVisible({ timeout: 15000 });
  });

  test('View created Vat', async ({ page }) => {
    await ensureCapboSession(page, "/vat");
    await searchList(page, name, {"testId":"vat-search","control":null,"route":"/vat"});
    await page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first().getByTestId("vat-view").or(page.getByTestId("vat-view").first()).first().click({ timeout: 10000 });
    await expect(page.getByTestId("vat-name")).toHaveValue(name, { timeout: 10000 });
  });

  test('Edit Vat (name)', async ({ page }) => {
    await ensureCapboSession(page, "/vat");
    await searchList(page, name, {"testId":"vat-search","control":null,"route":"/vat"});
    await page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: name }).first().getByTestId("vat-edit").or(page.getByTestId("vat-edit").first()).first().click({ timeout: 10000 });
    await fillAngularField(page, page.getByTestId("vat-name"), updatedName);
    await page.getByTestId("vat-save").click({ timeout: 15000 });
    await searchList(page, updatedName, {"testId":"vat-search","control":null,"route":"/vat"});
    await expect(page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first()).toBeVisible({ timeout: 15000 });
  });

  test('Validation: required fields gate the save button', async ({ page }) => {
    await ensureCapboSession(page, "/vat");
    await page.getByTestId("vat-create").click({ timeout: 15000 });
    // 3 required control(s) from Validators.required → empty form must not be savable
    await expect(page.getByTestId("vat-save")).toBeDisabled({ timeout: 8000 });
    // Touch + clear the name field → required error must appear
    await fillAngularField(page, page.getByTestId("vat-name"), 'x');
    await fillAngularField(page, page.getByTestId("vat-name"), '');
    await page.keyboard.press('Tab');
    await expect(page.locator('mat-error').first()).toBeVisible({ timeout: 5000 });
    await page.getByTestId("vat-cancel").click({ timeout: 8000 }).catch(() => {});
  });

  test('Delete Vat', async ({ page }) => {
    await ensureCapboSession(page, "/vat");
    await searchList(page, updatedName, {"testId":"vat-search","control":null,"route":"/vat"});
    await page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first().getByTestId("vat-edit").or(page.getByTestId("vat-edit").first()).first().click({ timeout: 10000 });
    await page.getByTestId("vat-delete").click({ timeout: 10000 });
    // Confirm dialog (testid from shared confirmation component)
    await page.getByTestId("confirm").click({ timeout: 8000 });
    await searchList(page, updatedName, {"testId":"vat-search","control":null,"route":"/vat"});
    await expect(page.locator("[data-testid=\"vat-row\"], table tbody tr, .mat-mdc-row, .mat-row").filter({ hasText: updatedName }).first()).toBeHidden({ timeout: 15000 });
  });

});
